package com.drivique.api.controller;
import com.drivique.api.dto.*; import com.drivique.api.service.CashPaymentService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/payments/cash") public class CashPaymentController {private final CashPaymentService service;public CashPaymentController(CashPaymentService service){this.service=service;}@PostMapping("/confirm") @PreAuthorize("hasAnyRole('EMPLOYEE','BRANCH_ADMIN')") public CashPaymentConfirmationResponseDTO confirm(@Valid @RequestBody CashPaymentConfirmationRequestDTO input,Authentication authentication){return service.confirm(input,authentication.getName());}}
